INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5822711, 848009, 110043, '<td valign="top">A nice idea with the bruised rose in the centre, although maybe the outer pair could be more perky. Nice colours and clarity. However i find the stems/vase a little distracting.</td>', 'A nice idea with the bruised rose in the centre, although maybe the outer pair could be more perky. Nice colours and clarity. However i find the stems/vase a little distracting.', '2010-01-22 07:12:34.000000', NULL, 1),
(5822714, 847563, 110043, '<td valign="top">An interesting composition. Would be nice to see a colour version of this. The shot looks a little bit noisey, possibly as a result of post processing.</td>', 'An interesting composition. Would be nice to see a colour version of this. The shot looks a little bit noisey, possibly as a result of post processing.', '2010-01-22 07:13:39.000000', NULL, 1),
(5822716, 847997, 110043, '<td valign="top">A nice use of lighting, but i find some of the other objects scattered around distracting.</td>', 'A nice use of lighting, but i find some of the other objects scattered around distracting.', '2010-01-22 07:14:50.000000', NULL, 1),
(5822717, 848250, 110043, '<td valign="top">Great lighting technique, I do find the horizontal (presumably fallen tree?) line a bit distracting.</td>', 'Great lighting technique, I do find the horizontal (presumably fallen tree?) line a bit distracting.', '2010-01-22 07:15:46.000000', NULL, 1),
